class Solution:
    def findPeakGrid(self, mat: List[List[int]]) -> List[int]:
        m, n = len(mat), len(mat[0])
        for i in range(m):
            for j in range(n):
                cur = mat[i][j]
                if i > 0 and mat[i - 1][j] >= cur:
                    continue
                if i + 1 < m and mat[i + 1][j] >= cur:
                    continue
                if j > 0 and mat[i][j - 1] >= cur:
                    continue
                if j + 1 < n and mat[i][j + 1] >= cur:
                    continue
                return [i, j]
        return [-1, -1]

