    def findPeakGrid(self, mat: List[List[int]]) -> List[int]:
        m, n = len(mat), len(mat[0])

        def argmax(col):
            r = 0
            for i in range(1, m):
                if mat[i][col] > mat[r][col]:
                    r = i
            return r

        lo, hi = 0, n - 1
        while lo < hi:
            mid = (lo + hi) // 2
            r = argmax(mid)
            if mat[r][mid] < mat[r][mid + 1]:
                lo = mid + 1
            else:
                hi = mid
        return [argmax(lo), lo]

