class Solution {
    public int[] findPeakGrid(int[][] mat) {
        int m = mat.length, n = mat[0].length;
        int lo = 0, hi = n - 1;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            int r = argmax(mat, m, mid);
            if (mat[r][mid] < mat[r][mid + 1]) lo = mid + 1;
            else hi = mid;
        }
        return new int[]{argmax(mat, m, lo), lo};
    }

    private int argmax(int[][] mat, int m, int col) {
        int r = 0;
        for (int i = 1; i < m; i++)
            if (mat[i][col] > mat[r][col]) r = i;
        return r;
    }
}

